from pathlib import Path
from html import escape as E
import json, re, shutil

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT
WORK=ROOT/'.work'
WORK.mkdir(exist_ok=True)
ASSET=OUT/'assets'
PAGES=[]

def icon(name,cls=''):
    s=(ASSET/'icons'/f'{name}.svg').read_text(encoding='utf-8')
    s=re.sub(r'<svg ',f'<svg aria-hidden="true" focusable="false" class="icon {cls}" ',s, count=1)
    return s
def btn(text,to=None,kind='primary',ico=None):
    content=(icon(ico) if ico else '')+E(text)
    return f'<a class="button {kind}" href="{to}.html">{content}</a>' if to else f'<button class="button {kind}" type="button" aria-disabled="true" title="Éste es un boceto estático">{content}</button>'
def tag(text,kind=''):
    return f'<span class="tag {kind}">{E(text)}</span>'
def note(title,text,kind='info',ico='circle-help'):
    return f'<aside class="notice {kind}">{icon(ico)}<div><strong>{E(title)}</strong><p>{E(text)}</p></div></aside>'
def field(label,value='',kind='text',hint='',error=''):
    fid='f-'+str(field.counter);field.counter+=1
    return f'<div class="field"><label for="{fid}">{E(label)}</label><input id="{fid}" type="{kind}" value="{E(value,quote=True)}" readonly '+(f'aria-invalid="true" ' if error else '')+f'aria-describedby="{fid}-hint"><p id="{fid}-hint" class="{ "error-text" if error else "hint"}">{E(error or hint)}</p></div>'
field.counter=0
def row(title,sub='',ico='chevron-right',to=None,tail=None):
    content=f'<span class="row-icon">{icon(ico)}</span><span class="row-copy"><strong>{E(title)}</strong>'+ (f'<small>{E(sub)}</small>' if sub else '')+'</span>'+ (f'<span class="row-tail">{E(tail)}</span>' if tail else icon('chevron-right'))
    return f'<a class="list-row" href="{to}.html">{content}</a>' if to else f'<div class="list-row">{content}</div>'
def choice(title,sub='',selected=False,ico='circle-check'):
    return f'<div class="choice {"selected" if selected else ""}">{icon(ico)}<div><strong>{E(title)}</strong><p>{E(sub)}</p></div><span class="choice-mark">{'<span class="sr-only">Seleccionada</span>' + icon("check") if selected else ""}</span></div>'
def section(title,right=''):
    return f'<div class="section-title"><h2>{E(title)}</h2><span>{E(right)}</span></div>'
def task(title='Preparar la entrega de UX',time='18:00',project='Facultad',state='',to='tarea-detalle',sub=''):
    return f'<a class="task {state}" href="{to}.html"><span class="task-check">{icon("check") if state=="done" else ""}</span><div><strong>{E(title)}</strong><p>{E(sub or time+" · "+project)}</p></div>'+ (tag('Hecha','success') if state=='done' else icon('chevron-right'))+'</a>'
def tasks():
    return task()+task('Revisar el prototipo con el grupo','19:30','UX · Alto voltaje')+task('Preparar la mochila','21:00','Personal')+section('Ya avanzaste','2 hechas')+task('Leer el capítulo de Sistemas','09:00','Facultad','done')+task('Enviar la propuesta a Clara','12:30','Trabajo','done')
def art(kind='compass'):
    artwork = f'''<svg class="art art-{kind}" viewBox="0 0 320 220" aria-hidden="true"><rect x="42" y="34" width="230" height="156" rx="28" fill="var(--lavender)" transform="rotate(-7 160 110)"/><path d="M38 180 Q96 150 127 176 T282 152" fill="none" stroke="var(--line)" stroke-width="2"/><circle cx="164" cy="108" r="74" fill="var(--surface)" stroke="var(--primary)" stroke-width="2"/><circle cx="164" cy="108" r="56" fill="none" stroke="var(--line)" stroke-dasharray="2 8" stroke-width="3"/><path d="m185 63-8 58-35 32 9-58Z" fill="var(--primary)"/><path d="m185 63-34 32 26 26Z" fill="var(--soft-blue)"/><circle cx="164" cy="108" r="5" fill="var(--surface)"/><circle cx="55" cy="61" r="11" fill="var(--accent)"/><path d="m257 170 7-11 7 11-7 11Z" fill="var(--primary)"/><path d="M269 35v18m-9-9h18" stroke="var(--primary)" stroke-width="2"/></svg>'''
    if kind != 'compass':
        motif={'mail':'mail','achievement':'trophy','restart':'sun'}.get(kind,kind)
        if (ASSET/'icons'/f'{motif}.svg').exists():
            start=artwork.index('<path d="m185')
            end=artwork.index('<circle cx="55"')
            glyph=icon(motif).replace('width="24"','x="126" y="70" width="76"').replace('height="24"','height="76"').replace('stroke="currentColor"','stroke="var(--primary)"').replace('class="icon ','class="illustration-glyph ')
            artwork=artwork[:start]+glyph+artwork[end:]
    return artwork

def empty(title,text,to,label='Crear mi primera tarea',kind='compass'):
    return f'<div class="empty">{art(kind)}<h2>{E(title)}</h2><p>{E(text)}</p></div>'+btn(label,to)
def steps(n):
    return '<div class="steps" aria-label="Paso '+str(n)+' de 5">'+''.join(f'<span class="{ "active" if x<=n else ""}"></span>' for x in range(1,6))+'</div>'
def pills(labels,active=0):
    return '<div class="pills">'+''.join(f'<span class="pill {"active" if i==active else ""}">{E(l)}</span>' for i,l in enumerate(labels))+'</div>'
def week():
    return '<div class="week">'+''.join(f'<div class="day {"selected" if n==4 else ""}"><span>{d}</span><strong>{n}</strong><i></i></div>' for n,d in zip(range(2,9),['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']))+'</div>'
def metric(value,label):return f'<div class="metric"><strong>{E(value)}</strong><span>{E(label)}</span></div>'
def person(name,sub,initials,to='amigo-racha',tail=None):
    return f'<a class="person" href="{to}.html"><span class="avatar">{E(initials)}</span><span class="row-copy"><strong>{E(name)}</strong><small>{E(sub)}</small></span>'+ (tag(tail) if tail else icon('chevron-right'))+'</a>'
def sheet(title,text,content='',action='Confirmar',to='hoy',danger=False):
    if 'bloqueo' in title.lower() or 'cupo' in title.lower(): origin='Bloqueo activo'; sub='Instagram y TikTok · 24:18 restantes'
    elif 'voltaje' in title.lower():origin='Alto voltaje';sub='4 integrantes · Todos pueden editar'
    elif 'organización' in title.lower():origin='Tu acompañamiento';sub='Consecuencias y avisos a tu medida'
    elif 'Entrega UX' in title:origin='Entrega UX';sub='3 de 8 tareas hechas'
    else:origin='Preparar la entrega de UX';sub='Hoy · 18:00 · Facultad'
    return f'<div class="origin-preview" aria-hidden="true"><div class="origin-title">{origin}</div><p>{sub}</p><div class="origin-task">{icon("file-text")}<span>Revisar los flujos del prototipo</span></div></div><section class="sheet" aria-label="{E(title)}"><div class="handle" aria-hidden="true"></div><h2>{E(title)}</h2><p>{E(text)}</p>{content}<div class="actions">{btn(action,to,"danger" if danger else "primary")}{btn("Volver sin cambios",sheet.back,"secondary")}</div></section>'
sheet.back='tarea-detalle'
def add(slug,title,group,body,nav='Hoy',subtitle='',cta=None,back='hoy',mode='normal',refs=''):
    PAGES.append(dict(slug=slug,title=title,group=group,body=body,nav=nav,subtitle=subtitle,cta=cta,back=back,mode=mode,refs=refs))

